cast:[
{name:'Bobby Wagner',role:'President of Football Operations',description:'Bryan’s trusted right-hand man. Calm, respected, candid, a bridge between ownership, players, and coaches.',quote:'Okay, Bryan. Walk me through what you’re thinking.'},
{name:'Scot McCloughan',role:'Analytics & Scouting Head',description:'The grumpy uncle. Blunt, skeptical, old-school scout with a sharp eye for value and an allergy to wasted draft picks.',quote:'Don’t get cute.'},
{name:'Pete Carroll',role:'Senior Football Adviser',description:'The competitive grandpa. Infectious enthusiasm, genuine care for players, Seahawks history, and a belief in development.',quote:'ALWAYS COMPETE!'},
{name:'Sarah',role:'Operations & Communications',description:'The assistant who had no idea what she signed up for. Brilliantly organized, dry-witted, and holding the circus together.',quote:'For legal purposes, we’re calling it player development.'},
{name:'Shane Steichen',role:'Head Coach',description:'The practical HC who wants to coach football while his bosses keep inventing new chaos. Detail-focused QB developer.',quote:'That’s great. Now who’s blocking?'},
{name:'Daniel Mercer',role:'Independent Beat Writer',description:'Fair but skeptical journalist who covered the franchise before and after relocation. Challenges ownership decisions.',quote:'Ambition is not a substitute for results.'},
{name:'Mina Kimes',role:'ESPN Documentary Host',description:'Perceptive documentary interviewer chronicling the first OKC season, team culture, family history, and expectations.',quote:'What happens when a new franchise expects to win immediately?'}],
